class BusBooking:
    def __init__(self, n: int):
        self.booked = set(); self.charges = {}; self.total = 0
    def toggle(self, seat: str) -> None:
        letter, row = seat[0], seat[1:]
        if seat in self.booked:
            self.booked.remove(seat); self.total -= self.charges.pop(seat)
            return
        adjacent = {'A': 'B', 'D': 'C', 'B': 'A', 'C': 'D'}[letter] + row
        cost = 3 if letter in 'AD' and adjacent in self.booked else 1
        self.booked.add(seat); self.charges[seat] = cost; self.total += cost
    def getTotalTime(self) -> int:
        return self.total
    def getMinTime(self) -> int:
        return len(self.booked)

